CREATE TABLE t1(w INT GENERATED ALWAYS AS (m*5),m INT AS (a*2) NOT NULL,a INT,x TEXT AS (typeof(c)) CHECK (x<>'blank'),b TEXT,y TEXT AS (substr(b,m/2,m/2+2)) STORED,c ANY,PRIMARY KEY(b,a)) WITHOUT ROWID; INSERT INTO t1(a,b,c) VALUES(1,'abcdef',5.5),(3,'cantaloupe',NULL); CREATE INDEX t1w ON t1(w); CREATE INDEX t1x ON t1(x) WHERE w BETWEEN 20 AND 40; UPDATE t1 SET a=a+100 WHERE w<20;